def rotate_payments_key(new_key):
    update_secret_store("payments_api_key", new_key)
    # server's cached-fetch pattern picks this up within CACHE_SECONDS
    log_rotation_event(secret="payments_api_key", rotated_by="ops-team")

def confirm_rotation_succeeded():
    recent_calls = get_recent_upstream_calls(limit=20)
    return all(call.status == "success" for call in recent_calls)
